<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>UNIFCO | طلب خدمة</title><style>:root{font-family:Tahoma,Arial,sans-serif;--navy:#1e315b;--red:#ce122d;--light:#f8f9fb}*{box-sizing:border-box}body{margin:0;background:var(--light);color:#132137}.wrap{width:min(860px,92%);margin:32px auto}.top{display:flex;justify-content:space-between;align-items:center;margin-bottom:20px}.logo{width:130px;height:76px;object-fit:contain}.card{background:#fff;border:1px solid #e3e8ef;border-radius:16px;padding:28px;box-shadow:0 10px 30px #13213710}h1{color:var(--navy);margin-top:0}.section{padding:18px 0;border-top:1px solid #edf0f5}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}label{display:grid;gap:6px;font-weight:700;font-size:14px}input,select,textarea{padding:12px;border:1px solid #ccd5e2;border-radius:9px;font:inherit}textarea{min-height:130px}.btn{border:0;border-radius:9px;padding:13px 18px;background:var(--red);color:#fff;font-weight:800;cursor:pointer}.back{color:var(--navy);text-decoration:none}.err{background:#fdecec;color:#9f1f1f;padding:12px;border-radius:9px;margin-bottom:15px}@media(max-width:700px){.grid{grid-template-columns:1fr}}</style></head><body><div class="wrap"><div class="top"><img class="logo" src="{{ route('brand.logo') }}" alt="UNIFCO"><a class="back" href="{{ route('public.home') }}">العودة للرئيسية</a></div><form class="card" method="POST" action="{{ route('public.request.store') }}">@csrf<input type="hidden" name="request_type" value="{{ $type }}"><h1>{{ $type === 'QUOTATION' ? 'طلب عرض سعر' : 'طلب صيانة طارئة' }}</h1><p>{{ $type === 'QUOTATION' ? 'أخبرنا بالخدمة أو المشروع المطلوب وسيتابع الفريق إعداد العرض.' : 'أرسل تفاصيل العطل والموقع ليتم التعامل معه كطلب طارئ.' }}</p>@if($errors->any())<div class="err">{{ $errors->first() }}</div>@endif<div class="section"><div class="grid"><label>نوع الخدمة<select name="service_category" required><option value="">اختر الخدمة</option><option>إدارة مرافق متكاملة</option><option>مشاريع كهربائية وميكانيكية</option><option>مولدات كهربائية</option><option>لوحات ATS</option><option>صيانة وقائية</option><option>صيانة تصحيحية</option><option>اختبارات وتشغيل</option><option>أخرى</option></select></label><label>المدينة / الموقع<input name="site_city" value="{{ old('site_city') }}"></label></div><label style="margin-top:14px">عنوان الطلب<input name="subject" value="{{ old('subject') }}" required></label><label style="margin-top:14px">التفاصيل<textarea name="details" required>{{ old('details') }}</textarea></label></div><div class="section"><h3>بيانات التواصل النهائية</h3><p style="color:#68758a">لا يلزم إنشاء حساب. نحتاج فقط البيانات التالية لإرسال ومتابعة العرض أو طلب الصيانة.</p><div class="grid"><label>اسم الشركة<input name="company_name" value="{{ old('company_name') }}" required></label><label>السجل التجاري<input name="commercial_registration" value="{{ old('commercial_registration') }}" required></label><label>البريد الإلكتروني<input type="email" name="email" value="{{ old('email') }}" required></label><label>رقم الجوال<input name="mobile" value="{{ old('mobile') }}" required></label></div></div><button class="btn" type="submit">إرسال الطلب</button></form></div></body></html>